def upgrade() -> None:
    # ### commands auto generated by Alembic - please adjust! ###

    # Manual edit to fix existing duplicated template names
    # Rename these duplicate templates using that templates id e.g. 'Duplicate Template (12345678)'
    op.execute(
        sa.text(
            """
            WITH ranked_templates AS (
                SELECT
                    id,
                    row_number() OVER (
                        PARTITION BY user_id, lower(btrim(name::text, E' \t\n\r'))
                        ORDER BY created_datetime, id
                    ) AS duplicate_number
                FROM user_template
                WHERE user_id IS NOT NULL
            )
            UPDATE user_template AS template
            SET name = template.name || ' (' || left(template.id::text, 8) || ')'
            FROM ranked_templates
            WHERE template.id = ranked_templates.id
            AND ranked_templates.duplicate_number > 1
            """
        )
    )

    op.create_index(
        "uq_user_template_user_id_normalised_name",
        "user_template",
        ["user_id", sa.literal_column("lower(btrim(name::text, E' \\t\\n\\r'))")],
        unique=True,
    )
    # ### end Alembic commands ###


